        new ArcTableColumn { Key = "name", Label = "Project" },
        new ArcTableColumn { Key = "owner", Label = "Owner", Width = 150, Sortable = false },
        new ArcTableColumn { Key = "budget", Label = "Budget", Width = 130, Numeric = true }
    },
    Rows = new[]
    {
        new Dictionary<string, object?>
        {
            ["id"] = "p1", ["name"] = "Harbour", ["owner"] = "Maya Chen", ["budget"] = 42000
        }
    }
};

table.SortChanged += (_, sort) => Reload(sort.Key, sort.Direction);
